package com.andye.warmod.block;import com.andye.warmod.block.entity.PhalanxBlockEntity;import com.andye.warmod.item.ModItems;import com.andye.warmod.phalanx.*;import net.minecraft.core.BlockPos;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;
public final class PhalanxStructure{private PhalanxStructure(){}public static boolean complete(ServerLevel level,BlockPos controller){for(var part:PhalanxPart.values()){BlockState s=level.getBlockState(controller.offset(part.offset()));if(!s.is(ModBlocks.PHALANX_TURRET)||s.getValue(PhalanxTurretBlock.PART)!=part)return false;}return level.getBlockEntity(controller)instanceof PhalanxBlockEntity;}public static void teardown(ServerLevel level,BlockPos any,BlockState state,boolean drops){if(!state.is(ModBlocks.PHALANX_TURRET))return;BlockPos controller=state.getValue(PhalanxTurretBlock.PART).controller(any);PhalanxBlockEntity be=level.getBlockEntity(controller)instanceof PhalanxBlockEntity p?p:null;if(be!=null&&be.teardown())return;if(be!=null)be.setTeardown(true);try{if(be!=null){PhalanxManager.unregister(level,be);PhalanxBulletManager.removeForTurret(level,be.turretId());}if(drops){Block.popResource(level,controller,new ItemStack(ModItems.PHALANX_TURRET));if(be!=null)for(int i=0;i<2;i++){ItemStack ammo=be.removeItemNoUpdate(i);if(!ammo.isEmpty())Block.popResource(level,controller,ammo);}}for(var part:PhalanxPart.values()){BlockPos p=controller.offset(part.offset());if(level.getBlockState(p).is(ModBlocks.PHALANX_TURRET))level.setBlock(p,Blocks.AIR.defaultBlockState(),Block.UPDATE_ALL);}}finally{if(be!=null)be.setTeardown(false);}}}
